func:
// Triggered by 'Split APRS Lines' whenever the APRS-IS server banner
// arrives -- first connect and every auto-reconnect -- so the filter is
// always re-applied. (Replaces the old one-shot login inject.)
msg.action = "write";
var call = (env.get("APRS_CALLSIGN") || "N0CALL").toUpperCase();
// pass -1 = receive-only login; no passcode needed
msg.payload = "user " + call + " pass -1 vers NodeRED-TAK 1.1 filter a/36.68/-90.31/34.98/-81.65\r\n";
return msg;

// Reassembles APRS-IS lines from the TCP stream.
// Output 1: one msg per APRS packet line.
// Output 2: login trigger -- fired every time the server banner arrives,
//           i.e. on first connect AND on every automatic reconnect.
var data = String(msg.payload || "");
var buffer = (flow.get("aprsBuffer") || "") + data;
var lines = buffer.split(/\r?\n/);
var tail = lines.pop() || "";
if (tail.length > 4096) tail = "";          // guard against a runaway partial line
flow.set("aprsBuffer", tail);
flow.set("aprsLastRx", Date.now());

var out = [];
var login = null;
for (var i = 0; i < lines.length; i++) {
    var line = lines[i].replace(/\s+$/, "");
    if (!line) continue;
    // Banner may be glued to a stale partial line from the previous connection
    var bm = line.match(/#\s*(aprsc|javAPRSSrvr)\b/i);
    if (bm && (bm.index === 0 || line.substring(0, bm.index).indexOf(":") === -1) && !/\d{2}:\d{2}:\d{2} GMT/.test(line)) {   // aprsc keep-alives ("# aprsc ... 28 Oct 2026 23:28:18 GMT ...") are not banners
        login = { payload: "login" };
        node.status({ fill: "yellow", shape: "dot", text: "server banner - logging in" });
        continue;
    }
    if (line.charAt(0) === "#") {
        if (/^#\s*logresp/i.test(line)) {
            node.status({ fill: "green", shape: "dot", text: line.substring(2, 70) });
        }
        continue;                            // keepalives / server comments
    }
    out.push({ payload: line });
}
return [out, login];

// APRS-IS line -> msg.aprs
// Handles: uncompressed + compressed positions (! = / @), objects (;),
// items ()), Mic-E (Kenwood/Yaesu radios), third-party (}) wrappers.
// Weather stations: wind dir/speed are stored as WEATHER data (msg.aprs.wx),
// never as course/speed, so WX markers don't move.

var TN = { latMin: 34.98, latMax: 36.68, lonMin: -90.31, lonMax: -81.65 };

var line = String(msg.payload || "");
if (!line || line.charAt(0) === "#") return null;

function b91(s) { var v = 0; for (var i = 0; i < s.length; i++) { v = v * 91 + (s.charCodeAt(i) - 33); } return v; }

function parseUncompressed(s) {
    var m = s.match(/^(\d{2})([\d ]{2}\.[\d ]{2})([NS])([\/\\0-9A-Z])(\d{3})([\d ]{2}\.[\d ]{2})([EW])(.)/);
    if (!m) return null;
    var lat = parseInt(m[1], 10) + parseFloat(m[2].replace(/ /g, "0")) / 60;   // spaces = position ambiguity
    var lon = parseInt(m[5], 10) + parseFloat(m[6].replace(/ /g, "0")) / 60;
    if (m[3] === "S") lat = -lat;
    if (m[7] === "W") lon = -lon;
    return { lat: lat, lon: lon, table: m[4], code: m[8], rest: s.substring(19), type: "plain" };
}

function parseCompressed(s) {
    if (s.length < 13) return null;
    var table = s.charAt(0);
    if (!/[\/\\A-Za-j]/.test(table)) return null;
    var latS = s.substring(1, 5), lonS = s.substring(5, 9);
    if (!/^[!-{]{4}$/.test(latS) || !/^[!-{]{4}$/.test(lonS)) return null;
    var r = { lat: 90 - b91(latS) / 380926, lon: -180 + b91(lonS) / 190463,
              table: table, code: s.charAt(9), rest: s.substring(13), type: "compressed",
              course: null, speedKnots: null, altitudeFt: null };
    if (s.charAt(10) !== " ") {
        var c = s.charCodeAt(10) - 33, sp = s.charCodeAt(11) - 33, t = s.charCodeAt(12) - 33;
        if ((t & 0x18) === 0x10) {
            r.altitudeFt = Math.pow(1.002, c * 91 + sp);           // GGA source: cs = altitude
        } else if (c >= 0 && c <= 89) {
            r.course = c * 4;
            r.speedKnots = Math.pow(1.08, sp) - 1;
        }
    }
    return r;
}

function parseMicE(dest, info) {
    var d = dest.replace(/-\d+$/, "");
    if (d.length < 6 || info.length < 9) return null;
    var digits = "", north = false, lonOff = 0, west = false;
    for (var i = 0; i < 6; i++) {
        var ch = d.charAt(i), v;
        if (ch >= "0" && ch <= "9") v = ch.charCodeAt(0) - 48;
        else if (ch >= "A" && ch <= "J") v = ch.charCodeAt(0) - 65;
        else if (ch >= "P" && ch <= "Y") v = ch.charCodeAt(0) - 80;
        else if (ch === "K" || ch === "L" || ch === "Z") v = 0;
        else return null;
        digits += v;
        var hi = (ch >= "P" && ch <= "Z");
        if (i === 3) north = hi;
        if (i === 4) lonOff = hi ? 100 : 0;
        if (i === 5) west = hi;
    }
    var lat = parseInt(digits.substring(0, 2), 10) + parseFloat(digits.substring(2, 4) + "." + digits.substring(4, 6)) / 60;
    if (!north) lat = -lat;
    var lonD = info.charCodeAt(1) - 28 + lonOff;
    if (lonD >= 180 && lonD <= 189) lonD -= 80;
    else if (lonD >= 190 && lonD <= 199) lonD -= 190;
    var lonM = info.charCodeAt(2) - 28; if (lonM >= 60) lonM -= 60;
    var lonH = info.charCodeAt(3) - 28;
    var lon = lonD + (lonM + lonH / 100) / 60;
    if (west) lon = -lon;
    var sp = info.charCodeAt(4) - 28, dc = info.charCodeAt(5) - 28, se = info.charCodeAt(6) - 28;
    var speed = sp * 10 + Math.floor(dc / 10); if (speed >= 800) speed -= 800;
    var course = (dc % 10) * 100 + se; if (course >= 400) course -= 400;
    var rest = info.substring(9), alt = null;
    var am = rest.match(/^[\x60'\]>]?([!-{]{3})\}/);
    if (am) { alt = (b91(am[1]) - 10000) * 3.28084; rest = rest.substring(am[0].length); }
    rest = rest.replace(/^[\x60'\]>]/, "").replace(/_.$/, "").replace(/[=^]$/, "");
    return { lat: lat, lon: lon, table: info.charAt(8), code: info.charAt(7), rest: rest, type: "mice",
             course: (course > 0 && course <= 360) ? course : null, speedKnots: speed, altitudeFt: alt };
}

function posAt(s) { return /^\d/.test(s) ? parseUncompressed(s) : parseCompressed(s); }

var hm = line.match(/^([^>]+)>([^,:]+)[^:]*:([\s\S]*)$/);
if (!hm) return null;
var sender = hm[1], dest = hm[2], info = hm[3];

if (info.charAt(0) === "}") {                   // third-party: unwrap once
    var inner = info.substring(1).match(/^([^>]+)>([^,:]+)[^:]*:([\s\S]*)$/);
    if (!inner) return null;
    sender = inner[1]; dest = inner[2]; info = inner[3];
}

var dti = info.charAt(0), pos = null, objName = null, kind = "station";
if (dti === "!" || dti === "=") pos = posAt(info.substring(1));
else if (dti === "/" || dti === "@") pos = posAt(info.substring(8));
else if (dti === ";") {
    if (info.length < 19 || info.charAt(10) === "_") return null;   // short or killed object
    objName = info.substring(1, 10).trim(); kind = "object";
    pos = posAt(info.substring(18));
} else if (dti === ")") {
    var im = info.match(/^\)([^!_]{3,9})([!_])/);
    if (!im || im[2] === "_") return null;
    objName = im[1].trim(); kind = "item";
    pos = posAt(info.substring(im[0].length));
} else if (dti === "\x60" || dti === "'") {
    pos = parseMicE(dest, info);
} else {
    var bang = info.indexOf("!");                // spec allows '!' up to 40 chars in
    if (bang > 0 && bang <= 40) pos = posAt(info.substring(bang + 1));
}
if (!pos || isNaN(pos.lat) || isNaN(pos.lon)) return null;
if (pos.lat < TN.latMin || pos.lat > TN.latMax || pos.lon < TN.lonMin || pos.lon > TN.lonMax) return null;

// Symbol table: '/' primary, anything else = alternate table (+ overlay char)
var table = pos.table, overlay = null;
if (table !== "/" && table !== "\\") {
    overlay = (pos.type === "compressed" && table >= "a" && table <= "j") ? String(table.charCodeAt(0) - 97) : table;
    table = "\\";
}

var rest = pos.rest || "";
var course = pos.course !== undefined ? pos.course : null;
var speedKnots = pos.speedKnots !== undefined ? pos.speedKnots : null;
var altitudeFt = pos.altitudeFt !== undefined ? pos.altitudeFt : null;
var isWx = (pos.code === "_");
var wx = null;

if (pos.type === "plain") {
    var ext = rest.match(/^([\d .]{3})\/([\d .]{3})/);
    if (ext) {
        if (isWx || /^g/.test(rest.substring(7))) {
            isWx = true;                         // weather: DDD/SSS = wind dir / mph
            wx = { windDir: /^\d{3}$/.test(ext[1]) ? parseInt(ext[1], 10) : null,
                   windMph: /^\d{3}$/.test(ext[2]) ? parseInt(ext[2], 10) : null };
        } else if (/^\d{3}$/.test(ext[1]) && /^\d{3}$/.test(ext[2])) {
            var c = parseInt(ext[1], 10);
            course = (c > 0 && c <= 360) ? c : null;
            speedKnots = parseInt(ext[2], 10);
        }
        rest = rest.substring(7);
    } else {
        rest = rest.replace(/^(PHG\d{4}|RNG\d{4}|DFS\d{4})/, "");
    }
} else if (isWx && pos.type === "compressed") {
    wx = { windDir: course, windMph: speedKnots !== null ? speedKnots * 1.15078 : null };
}
if (isWx) {
    course = null; speedKnots = null;            // never a track for a weather station
    wx = wx || {};
    var blob = (rest.match(/^[cgstrpPhbLl#\d .\-]*/) || [""])[0];
    var g = blob.match(/g(\d{3})/); if (g) wx.gustMph = parseInt(g[1], 10);
    var t = blob.match(/t(-\d{2}|\d{3})/);       // APRS temps are already deg F (t068, t-05)
    if (t) { var tf = parseInt(t[1], 10); if (tf >= -80 && tf <= 140) wx.tempF = tf; }
    var h = blob.match(/h(\d{2})/); if (h) { var hv = parseInt(h[1], 10); wx.humidity = hv === 0 ? 100 : hv; }
    var b = blob.match(/b(\d{5})/); if (b) wx.pressureMb = parseInt(b[1], 10) / 10;
    var r = blob.match(/r(\d{3})/); if (r) wx.rain1hIn = parseInt(r[1], 10) / 100;
    rest = rest.substring(blob.length);
}

var am2 = rest.match(/\/A=(-?\d{5,6})/);
if (am2) { altitudeFt = parseInt(am2[1], 10); rest = rest.replace(am2[0], ""); }

var name = objName || sender;
var uid = (kind === "station" ? "APRS-" : "APRS-OBJ-") + name.replace(/[^A-Za-z0-9_-]/g, "_");

msg.aprs = {
    callsign: name,
    sender: sender,
    kind: kind,
    uid: uid,
    lat: pos.lat,
    lon: pos.lon,
    hae: altitudeFt !== null ? altitudeFt * 0.3048 : 0,
    altitudeFt: altitudeFt,
    course: course,
    speedKnots: speedKnots,
    speedMs: speedKnots !== null ? speedKnots * 0.514444 : 0,
    isWx: isWx,
    wx: wx,
    temperatureF: (wx && wx.tempF !== undefined) ? wx.tempF : null,
    symbolTable: table,
    symbolCode: pos.code,
    symbolKey: table + pos.code,
    overlay: overlay,
    isFixed: isWx || kind !== "station" || !speedKnots || speedKnots < 1,
    format: pos.type,
    comment: rest.trim(),
    raw: line,
    received: Date.now()
};
return msg;

// Drops repeats of an unchanged position, but lets a repeat through once
// RESEND_MS has passed, so fixed stations (digis, iGates, WX, objects)
// keep getting refreshed and never fall off the map.
var RESEND_MS = 10 * 60 * 1000;
var PRUNE_MS  = 3 * 60 * 60 * 1000;   // forget stations not heard for 3h

var a = msg.aprs;
if (!a) return null;

var key = [
    a.lat.toFixed(5), a.lon.toFixed(5), a.course,
    a.speedKnots === null ? "" : Math.round(a.speedKnots),
    a.altitudeFt === null ? "" : Math.round(a.altitudeFt),
    a.wx ? JSON.stringify(a.wx) : ""
].join("|");

var now = Date.now();
var seen = context.get("seen") || {};
var prev = seen[a.uid];
if (prev && prev.k === key && (now - prev.t) < RESEND_MS) return null;
seen[a.uid] = { k: key, t: now };

var n = (context.get("n") || 0) + 1;
if (n >= 500) {
    n = 0;
    for (var u in seen) { if (now - seen[u].t > PRUNE_MS) delete seen[u]; }
}
context.set("n", n);
context.set("seen", seen);
node.status({ fill: "green", shape: "dot", text: Object.keys(seen).length + " stations tracked" });
return msg;

initialize:
// One-time cleanup of the old per-station "last_<uid>" flow keys
var removed = 0;
(flow.keys() || []).forEach(function (k) {
    if (k.indexOf("last_") === 0) { flow.set(k, undefined); removed++; }
});
if (removed) node.log("Removed " + removed + " old APRS dedup keys from flow context");

func:
let a = msg.aprs;

if (!a) return null;

function esc(v) {
    return String(v == null ? "" : v)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&apos;");
}

function iso(ms) {
    return new Date(ms).toISOString();
}

// ============================================================
// APRS SYMBOL → TAK TYPE
// ============================================================

let symbolMap = {

    // Ground vehicles (primary table)
    "/>": { name: "Car", cot: "a-f-G-E-V-C" },
    "/j": { name: "Jeep", cot: "a-f-G-E-V-C" },
    "/k": { name: "Truck", cot: "a-f-G-E-V-C" },
    "/v": { name: "Van", cot: "a-f-G-E-V-C" },
    "/u": { name: "Heavy Truck", cot: "a-f-G-E-V-C" },
    "/<": { name: "Motorcycle", cot: "a-f-G-E-V-C" },

    // Aircraft (primary table)
    "/^": { name: "Aircraft", cot: "a-f-A-C-F" },
    "/'": { name: "Small Aircraft", cot: "a-f-A-C-F" },
    "/g": { name: "Glider", cot: "a-f-A-C-F" },
    "/X": { name: "Helicopter", cot: "a-f-A-C-H" },

    // Maritime (primary table)
    "/s": { name: "Powerboat", cot: "a-f-S-X-R" },
    "/Y": { name: "Yacht", cot: "a-f-S-X-R" },

    // Person (primary table)
    "/[": { name: "Person", cot: "a-f-G-U-C-I" },

    // Emergency / public safety (primary table)
    "/a": { name: "Ambulance", cot: "a-f-G-E-V-C" },
    "/f": { name: "Fire Truck", cot: "a-f-G-E-V-C" },
    "/P": { name: "Police", cot: "a-f-G-U-U-L-C" },

    // Infrastructure / radio (primary table) - verified against aprs.org symbol charts
    "/#": { name: "Digipeater", cot: "a-f-G-U-U-S-R-W" },
    "/&": { name: "HF Gateway (iGate)", cot: "a-f-G-U-U-S-R-W" },
    "/n": { name: "APRS Node", cot: "a-f-G-U-U-S-R-W" },
    "/L": { name: "PC/Software Station", cot: "a-f-G-U-U-S" },

    // Weather (primary table) - corrected: "_" is the real weather symbol, not "W"
    "/_": { name: "Weather Station", cot: "a-f-G-E-S-E" },
    "/U": { name: "Bus", cot: "a-f-G-E-V-C" },

    // Satellite (primary table)
    "/S": { name: "Satellite", cot: "a-f-P-S" },

    // Signal / net-control stations (alternate table) - true "Signal Unit" match
    "\\a": { name: "ARES/RACES/WinLink Station", cot: "a-f-G-U-U-S" },

    // Alternate-table / overlay versions (now parsed, e.g. "D#" overlay digis)
    "\\#": { name: "Digipeater", cot: "a-f-G-U-U-S-R-W" },
    "\\&": { name: "Gateway (iGate)", cot: "a-f-G-U-U-S-R-W" },
    "\\_": { name: "Weather Station", cot: "a-f-G-E-S-E" },
    "\\>": { name: "Car", cot: "a-f-G-E-V-C" }
};

let symbolTable = a.symbolTable || "/";
let key = a.symbolKey || (symbolTable + a.symbolCode);

let symbol = symbolMap[key] || {
    name: "APRS Station",
    cot: "a-f-G-U-U-S"
};

let cotType = symbol.cot;
let symbolName = symbol.name;
// ============================================================
// TIMES
// ============================================================

const now = Date.now();

const staleSeconds = a.isFixed ? 3600 : 1800;   // fixed stations/WX/objects stay 60 min

const time = iso(now);
const stale = iso(now + staleSeconds * 1000);

// ============================================================
// MARKER LABEL
// ============================================================

let labelParts = [
    a.callsign
];

labelParts.push(symbolName);

if (
    a.temperatureF !== null &&
    a.temperatureF !== undefined
) {
    labelParts.push(
        a.temperatureF + "°F"
    );
}

if (
    a.course !== null &&
    a.course !== undefined
) {
    labelParts.push(
        String(Math.round(a.course)).padStart(3, "0") + "°"
    );
}

if (
    a.speedKnots !== null &&
    a.speedKnots !== undefined
) {
    labelParts.push(
        Math.round(a.speedKnots * 1.15078) + " mph"
    );
}

if (
    a.altitudeFt !== null &&
    a.altitudeFt !== undefined
) {
    labelParts.push(
        Math.round(a.altitudeFt) + " ft"
    );
}

// Weather: show wind in the label (never as a track)
if (a.isWx && a.wx && a.wx.windMph !== null && a.wx.windMph !== undefined) {
    labelParts.push("Wind " +
        (a.wx.windDir !== null && a.wx.windDir !== undefined ? String(a.wx.windDir).padStart(3, "0") + "° " : "") +
        Math.round(a.wx.windMph) + " mph" +
        (a.wx.gustMph !== undefined ? " G" + a.wx.gustMph : ""));
}

const markerLabel = labelParts.join(" | ");

// ============================================================
// TRACK
// ============================================================

let track = "";
if (a.isWx) { a.course = null; }   // weather stations never get a track

if (
    a.course !== null &&
    a.course !== undefined
) {

    let speed = 0;

    if (
        a.speedMs !== null &&
        a.speedMs !== undefined
    ) {
        speed = a.speedMs;
    }

    track =
        '<track' +
        ' course="' +
        Number(a.course).toFixed(1) +
        '"' +
        ' speed="' +
        Number(speed).toFixed(2) +
        '"' +
        '/>';
}

// ============================================================
// REMARKS
// ============================================================

let remarks = [];

remarks.push(
    "APRS: " + a.callsign
);

remarks.push(
    "Type: " + symbolName
);

if (
    a.temperatureF !== null &&
    a.temperatureF !== undefined
) {
    remarks.push(
        "Temp: " + a.temperatureF + "°F"
    );
}

remarks.push(
    "Symbol: " + (a.overlay || a.symbolTable) + a.symbolCode + (a.overlay ? " (overlay " + a.overlay + ")" : "")
);

if (
    a.course !== null &&
    a.course !== undefined
) {
    remarks.push(
        "Course: " +
        Math.round(a.course) +
        "°"
    );
}

if (
    a.speedKnots !== null &&
    a.speedKnots !== undefined
) {
    remarks.push(
        "Speed: " +
        Math.round(a.speedKnots * 1.15078) +
        " mph"
    );
}

if (
    a.altitudeFt !== null &&
    a.altitudeFt !== undefined
) {
    remarks.push(
        "Altitude: " +
        Math.round(a.altitudeFt) +
        " ft"
    );
}

if (a.kind && a.kind !== "station") {
    remarks.push("APRS " + a.kind + " posted by " + a.sender);
}

if (a.isWx && a.wx) {
    if (a.wx.windMph !== null && a.wx.windMph !== undefined) {
        remarks.push("Wind: " + (a.wx.windDir !== null && a.wx.windDir !== undefined ? a.wx.windDir + "° @ " : "") + Math.round(a.wx.windMph) + " mph");
    }
    if (a.wx.gustMph !== undefined) remarks.push("Gust: " + a.wx.gustMph + " mph");
    if (a.wx.humidity !== undefined) remarks.push("Humidity: " + a.wx.humidity + "%");
    if (a.wx.pressureMb !== undefined) remarks.push("Pressure: " + a.wx.pressureMb.toFixed(1) + " mb");
    if (a.wx.rain1hIn !== undefined) remarks.push("Rain 1h: " + a.wx.rain1hIn.toFixed(2) + " in");
}

if (a.comment) {
    remarks.push(
        "Comment: " +
        a.comment
    );
}

// ============================================================
// CoT
// ============================================================

const cot =

    '<?xml version="1.0" encoding="UTF-8"?>' +

    '<event' +

        ' version="2.0"' +

        ' uid="' +
        esc(a.uid) +
        '"' +

        ' type="' +
        esc(cotType) +
        '"' +

        ' how="m-g"' +

        ' time="' +
        time +
        '"' +

        ' start="' +
        time +
        '"' +

        ' stale="' +
        stale +
        '">' +

        '<point' +

            ' lat="' +
            Number(a.lat).toFixed(6) +
            '"' +

            ' lon="' +
            Number(a.lon).toFixed(6) +
            '"' +

            ' hae="' +
            Number(a.hae || 0).toFixed(1) +
            '"' +

            ' ce="9999999.0"' +

            ' le="9999999.0"' +

        '/>' +

        '<detail>' +

            '<contact' +

                ' callsign="' +
                esc(markerLabel) +
                '"' +

            '/>' +

            (cotType === 'a-f-A-C-F' ?
                '<usericon iconsetpath="66f14976-4b62-4023-8edb-d8d2ebeaa336/Public Safety Air/CIV_FIXED_CAP.png"/>' :
            cotType === 'a-f-A-C-H' ?
                '<usericon iconsetpath="66f14976-4b62-4023-8edb-d8d2ebeaa336/Public Safety Air/CIV_ROTOR_ISR.png"/>' :
                '') +

            '<color argb="-38476"/>' +

            track +

            '<remarks>' +
                esc(remarks.join(" | ")) +
            '</remarks>' +

        '</detail>' +

    '</event>\r\n';

msg.payload = cot;

msg.cot = cot;

msg.topic = a.callsign;

msg.aprsSymbol = a.symbolCode;

msg.aprsSymbolName = symbolName;

msg.cotType = cotType;

return msg;
